<section class="page-banner compact"><div class="container page-banner-inner"><div><p class="eyebrow">INVENTORY / CATALOG</p><h1>What's on hand.</h1><p class="lead">Keep product prices, images, and stock levels accurate. Archive items without erasing their sales history.</p></div><a class="button primary" href="<?= site_url('products/new') ?>">Add product <span aria-hidden="true">↗</span></a></div></section>

<section class="section listing-section"><div class="container">
    <div class="table-summary"><div><p class="eyebrow">THE CATALOG</p><h2><?= count($products) ?> products</h2></div><div class="table-tools"><label class="search-field"><span class="sr-only">Search products</span><input type="search" placeholder="Search products" data-catalog-search autocomplete="off"><span aria-hidden="true">⌕</span></label></div></div>
    <?php if (session('notice')): ?><p class="notice" role="status"><?= esc(session('notice')) ?></p><?php endif; ?>
    <?php if (session('form_error')): ?><p class="form-alert" role="alert"><?= esc(session('form_error')) ?></p><?php endif; ?>
    <?php if ($products === []): ?><div class="empty-state"><span class="empty-glyph" aria-hidden="true">□</span><h3>Start with your first product</h3><p>Add an item, its price, and the quantity available for sale.</p><a class="button primary" href="<?= site_url('products/new') ?>">Add product</a></div>
    <?php else: ?><div class="product-grid" data-catalog-list><?php foreach ($products as $product): ?>
        <article class="product-card <?= (int) $product['is_active'] === 0 ? 'is-archived' : '' ?>" data-product-name="<?= esc(mb_strtolower($product['name']), 'attr') ?>">
            <div class="product-image"><img src="<?= esc(marketmate_product_image_url($product['image'] ?? null), 'attr') ?>" alt="<?= esc($product['name'], 'attr') ?>" loading="lazy"><span class="product-status <?= (int) $product['is_active'] === 0 ? 'status-archived' : ((int) $product['stock_quantity'] <= 5 ? 'status-low' : '') ?>"><?= (int) $product['is_active'] === 0 ? 'Archived' : ((int) $product['stock_quantity'] <= 5 ? 'Low stock' : 'In catalog') ?></span></div>
            <div class="product-body"><div class="product-title-row"><h3><?= esc($product['name']) ?></h3><strong><?= marketmate_money($product['price']) ?></strong></div><p><?= (int) $product['stock_quantity'] ?> units available</p><div class="product-actions"><a class="table-link" href="<?= site_url('products/' . $product['id'] . '/edit') ?>">Edit product <span aria-hidden="true">↗</span></a><form method="post" action="<?= site_url('products/' . $product['id'] . ((int) $product['is_active'] === 1 ? '/archive' : '/restore')) ?>" data-confirm="<?= (int) $product['is_active'] === 1 ? 'Archive this product? It will not appear at checkout.' : 'Return this product to the catalog?' ?>"><?= csrf_field() ?><button class="quiet-action" type="submit"><?= (int) $product['is_active'] === 1 ? 'Archive' : 'Restore' ?></button></form></div></div>
        </article>
    <?php endforeach; ?></div><p class="search-empty" data-search-empty hidden>No matching products. Try a different search.</p><?php endif; ?>
</div></section>
